    48	 * @param children? An optional list of properties to watch (by default will watch for all the observable properties)
    49	 */
    50	const subscribeProperties = <C extends keyof Subscribables<P>, P extends Partial<Record<C, ko.Subscribable>>>(
    51	  object: P,
    52	  onUpdate: (updates: Partial<UnwrappedValues<P>>) => void,
    53	  children?: C[],
