    59	    .filter(child => ko.isSubscribable(object?.[child]))
    60	    .map(child => {
    61	      const subscribable = object[child];
    62	      return subscribable?.subscribe((value: Unwrapped<typeof subscribable>) => {
    63	        onUpdate({[child]: value} as Partial<UnwrappedValues<P>>);
    64	      });
    65	    });
    66	
    67	  return {
    68	    dispose: () => subscriptions.forEach(subscription => subscription?.dispose()),
    69	  };
