    58	        onUpdate({[child]: value} as Partial<Pick<UnwrappedValues<P>, C>>);
    59	      });
    60	    });
    61	
    62	  return {
    63	    dispose: () => subscriptions.forEach(subscription => subscription?.dispose()),
    64	  };
    65	};
    66	
    67	/**
    68	 * Registers a react component against the ko world.
    69	 *
    70	 * @param name Name of the component to register. can be used a `<component-name>` directly in ko
    71	 * @param component The React component to register
    72	 */
    73	export function registerReactComponent<Props>(name: string, component: React.ComponentType<Props>) {
    74	  if (ko.components.isRegistered(name)) {
    75	    return;
    76	  }
    77	
    78	  ko.components.register(name, {
    79	    template: '<!-- -->', // We do not need any particular template as this is going to be replaced by react content
    80	    viewModel: {
    81	      createViewModel: (params: Props, {element}: {element: HTMLElement}) => {
    82	        let state: Props = resolveObservables(params) as Props;
    83	        const root = createRoot(element);
    84	        const subscription = subscribeProperties(params, updates => {
    85	          state = {...state, ...updates};
    86	          root.render(React.createElement(component, state));
    87	        });
    88	        return {
    89	          dispose() {
    90	            root.unmount();
    91	            subscription.dispose();
    92	          },
    93	        };
    94	      },
    95	    },
    96	  });
    97	}
    98	
    99	export const useKoSubscribableChildren = <P, C extends keyof P>(
   100	  parent: P,
   101	  children: C[],
   102	): Pick<UnwrappedValues<P>, C> => {
   103	  const [state, setState] = useState<Pick<UnwrappedValues<P>, C>>(resolveObservables(parent, children));
   104	  useEffect(() => {
   105	    const subscription = subscribeProperties(
   106	      parent,
   107	      updates => setState(currentState => ({...currentState, ...updates})),
   108	      children,
   109	    );
   110	    return () => subscription.dispose();
   111	  }, [parent]);
   112	
   113	  return state;
   114	};
